    public static string Text => $"Manual e procedimentos obrigatórios FinanceForgeLab — versão {Version}\n\n" +
        string.Join("\n\n", Procedures.Select(p => $"[{p.Id}] {p.Title}\nQuando: {p.Trigger}\n" +
            string.Join("\n", p.Steps.Select((s,i) => $"{i+1}. {s}")) + $"\nVerificação final: {p.Completion}"));
}
